SELECT * FROM (SELECT e.event_id,'ROP:'||s.operation_id case_id,e.activity,e.timestamp FROM (SELECT 'ROP:'||operation_id event_id,'Rough Rolling Completed' activity,finished_at timestamp,operation_id source_key FROM rolling_operation_history WHERE finished_at IS NOT NULL AND (phase_code='R')) e JOIN rolling_operation_history s ON s.operation_id=e.source_key UNION ALL SELECT e.event_id,'ROP:'||s.operation_id case_id,e.activity,e.timestamp FROM (SELECT 'ROP:'||operation_id event_id,'Finish Rolling Completed' activity,finished_at timestamp,operation_id source_key FROM rolling_operation_history WHERE finished_at IS NOT NULL AND (phase_code='F')) e JOIN rolling_operation_history s ON s.operation_id=e.source_key) ORDER BY case_id,timestamp,event_id;
